# %% pts/tests/integration/cmds/test_doctor.pct.py 3
CHARSET = string.ascii_lowercase + string.digits


class TestIsValidIndexName:
    """Index-name validity is derived from config but accepts legacy formats."""

    def test_current_format(self):
        assert is_valid_index_name("20260620_tbmxs5__pi-rpc-set-model", CHARSET, 6)

    def test_name_with_spaces(self):
        assert is_valid_index_name(
            "20240805_000000_E4Dzy__Notion integration test", CHARSET, 6
        )

    def test_name_containing_double_underscore(self):
        assert is_valid_index_name("20260623_9qkepq__sesh-ui__ui-links", CHARSET, 6)

    def test_legacy_datetime_timestamp_mixed_case_subid(self):
        assert is_valid_index_name("20250427_000000_VOGj7__some-name", CHARSET, 6)

    def test_legacy_date_only_short_subid(self):
        assert is_valid_index_name("20251210_bnesz__my-servers", CHARSET, 6)

    def test_no_separator(self):
        assert not is_valid_index_name("box-with-no-id", CHARSET, 6)

    def test_date_prefix_but_no_subid(self):
        assert not is_valid_index_name("20260227_mysystem-obsidian", CHARSET, 6)

    def test_empty_name(self):
        assert not is_valid_index_name("20260620_tbmxs5__", CHARSET, 6)

    def test_invalid_date(self):
        assert not is_valid_index_name("20261399_tbmxs5__box", CHARSET, 6)

    def test_subid_wrong_length(self):
        assert not is_valid_index_name("20260620_tbmx__box", CHARSET, 6)

    def test_subid_outside_charset_and_not_legacy(self):
        assert not is_valid_index_name("20260620_TBMXS5__box", CHARSET, 6)

    def test_respects_configured_subid_length(self):
        # With subid_length=6, a 6-char subid is valid; with 4 it is not
        # (5-char legacy subids are always accepted).
        assert is_valid_index_name("20260620_tbmxs5__box", CHARSET, 6)
        assert not is_valid_index_name("20260620_tbmxs5__box", CHARSET, 4)


