# %% pts/tests/integration/cmds/test_doctor.pct.py 4
def _doctor(config_path, **kwargs):
    return asyncio.run(run_doctor(config_path=config_path, **kwargs))


def _findings(report, check_name):
    return report["checks"][check_name]["findings"]


def _write_registration(
    config, storage_location, index_name, groups=None, parents=None
):
    """Hand-create a registration dir with a valid boxmeta.toml (drift simulation)."""
    reg_path = config.local_store_path / storage_location / index_name
    reg_path.mkdir(parents=True)
    (reg_path / const.BOX_METAFILE_REL_PATH).write_text(
        tomli_w.dumps(
            {
                "storage_location": storage_location,
                "creator_hostname": "test-host",
                "groups": groups or [],
                "parents": parents or [],
            }
        )
    )
    return reg_path

