@pytest.mark.integration
def test_doctor_unregistered_and_malformed(temp_boxyard):
    remote_name, remote_rclone_path, config, config_path, data_path = temp_boxyard

    new_box(config_path=config_path, box_name="real-box", storage_location=remote_name)

    # Hand-created folder: unregistered AND malformed
    (config.user_boxes_path / "hand-made-folder").mkdir()
    # Valid-looking index name but no registration: unregistered only
    (config.user_boxes_path / "20990101_zzzzz__fake-box").mkdir()
    # Stray file: unregistered-folder finding
    (config.user_boxes_path / "stray.txt").write_text("stray")

    report = _doctor(config_path, check_remote=False)
    assert not report["healthy"]

    unregistered_paths = {f["path"] for f in _findings(report, "unregistered-folder")}
    assert str(config.user_boxes_path / "hand-made-folder") in unregistered_paths
    assert str(config.user_boxes_path / "20990101_zzzzz__fake-box") in unregistered_paths
    assert str(config.user_boxes_path / "stray.txt") in unregistered_paths

    malformed_paths = {f["path"] for f in _findings(report, "malformed-name")}
    assert str(config.user_boxes_path / "hand-made-folder") in malformed_paths
    assert str(config.user_boxes_path / "20990101_zzzzz__fake-box") not in malformed_paths

    # The properly created box is not flagged
    assert not any("real-box" in p for p in unregistered_paths | malformed_paths)

