@pytest.mark.integration
def test_doctor_broken_registration(temp_boxyard):
    remote_name, remote_rclone_path, config, config_path, data_path = temp_boxyard

    box1 = new_box(config_path=config_path, box_name="box-no-meta", storage_location=remote_name)
    box2 = new_box(config_path=config_path, box_name="box-bad-meta", storage_location=remote_name)

    # Remove one boxmeta.toml, corrupt the other
    (config.local_store_path / remote_name / box1 / const.BOX_METAFILE_REL_PATH).unlink()
    (config.local_store_path / remote_name / box2 / const.BOX_METAFILE_REL_PATH).write_text(
        "this is [not valid toml"
    )
    # Stray file directly in the local store
    (config.local_store_path / remote_name / "stray.txt").write_text("stray")

    report = _doctor(config_path, check_remote=False)
    assert not report["healthy"]

    messages = [f["message"] for f in _findings(report, "broken-registration")]
    assert any(box1 in m and "has no boxmeta.toml" in m for m in messages)
    assert any(box2 in m and "fails to load" in m for m in messages)
    assert any("Stray file" in m for m in messages)

    # Broken registrations are excluded from the stale-cache comparison
    stale_cache_messages = [f["message"] for f in _findings(report, "stale-cache")]
    assert not any(box1 in m or box2 in m for m in stale_cache_messages)

