@pytest.mark.integration
def test_doctor_stale_cache(temp_boxyard):
    remote_name, remote_rclone_path, config, config_path, data_path = temp_boxyard

    box1 = new_box(config_path=config_path, box_name="cached-box", storage_location=remote_name)

    # Registration created behind boxyard's back: missing from the cache
    _write_registration(config, remote_name, "20990101_aaaaaa__hand-registered")
    # Registration modified behind boxyard's back: cache entry out of date
    bm_path = config.local_store_path / remote_name / box1 / const.BOX_METAFILE_REL_PATH
    bm_data = tomllib.loads(bm_path.read_text())
    bm_data["groups"] = ["drifted-group"]
    bm_path.write_text(tomli_w.dumps(bm_data))

    report = _doctor(config_path, check_remote=False)
    messages = [f["message"] for f in _findings(report, "stale-cache")]
    assert any("20990101_aaaaaa__hand-registered" in m and "missing from the cache" in m for m in messages)
    assert any(box1 in m and "out of date" in m for m in messages)

    # Registration deleted behind boxyard's back: cached entry with no registration
    shutil.rmtree(config.local_store_path / remote_name / "20990101_aaaaaa__hand-registered")
    # (recreate the cache mismatch: the cache still doesn't know about the deletion
    # of a box it never knew of, so use box1 instead)
    shutil.rmtree(config.local_store_path / remote_name / box1)
    report = _doctor(config_path, check_remote=False)
    messages = [f["message"] for f in _findings(report, "stale-cache")]
    assert any(box1 in m and "no such registration" in m for m in messages)

    # Missing cache file
    config.boxyard_meta_path.unlink()
    report = _doctor(config_path, check_remote=False)
    messages = [f["message"] for f in _findings(report, "stale-cache")]
    assert any("does not exist" in m for m in messages)

