@pytest.mark.integration
def test_doctor_stale_meta_mirror(temp_boxyard):
    remote_name, remote_rclone_path, config, config_path, data_path = temp_boxyard

    box1 = new_box(config_path=config_path, box_name="local-box", storage_location=remote_name)
    asyncio.run(sync_box(config_path=config_path, box_index_name=box1))

    # A box that exists only on the remote (as if created by another machine)
    foreign_index_name = "20990101_cccccc__foreign-box"
    foreign_path = (
        remote_rclone_path / "boxyard" / const.REMOTE_BOXES_REL_PATH / foreign_index_name
    )
    foreign_path.mkdir(parents=True)
    (foreign_path / const.BOX_METAFILE_REL_PATH).write_text(
        tomli_w.dumps(
            {
                "storage_location": remote_name,
                "creator_hostname": "other-machine",
                "groups": [],
                "parents": [],
            }
        )
    )

    report = _doctor(config_path)
    findings = _findings(report, "stale-meta-mirror")
    assert len(findings) == 1
    assert findings[0]["storage_location"] == remote_name
    assert findings[0]["missing_index_names"] == [foreign_index_name]
    assert "sync-missing-meta" in findings[0]["hint"]

    # Skippable for offline use (both remote checks)
    report = _doctor(config_path, check_remote=False)
    assert report["checks"]["stale-meta-mirror"]["skipped"]
    assert report["checks"]["tombstoned-box"]["skipped"]
    assert not _findings(report, "stale-meta-mirror")
    assert report["healthy"]

    # Restricting to a storage location without drift reports nothing
    report = _doctor(config_path, storage_locations=["fake"])
    assert not _findings(report, "stale-meta-mirror")

    # Unknown storage locations are rejected loudly
    with pytest.raises(ValueError):
        _doctor(config_path, storage_locations=["nope"])

